mapper.select:
SELECT * FROM conversation_session WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND status=#{status}

    AND (last_access_at < #{cursor.time} OR (last_access_at=#{cursor.time} AND session_id < #{cursor.id}))

ORDER BY last_access_at DESC, session_id DESC LIMIT #{limit}

SELECT session_id FROM conversation_session WHERE status='DELETED'
    AND deleted_at < TIMESTAMPADD(DAY, -#{retentionDays}, CURRENT_TIMESTAMP(6))
ORDER BY deleted_at, session_id LIMIT #{limit}

mapper.delete:
DELETE FROM agent_run_state WHERE session_id=#{sessionId}
    AND NOT EXISTS (SELECT 1 FROM agent_run_submission s WHERE s.run_id=agent_run_state.run_id)
    AND NOT EXISTS (SELECT 1 FROM agent_run_event e WHERE e.run_id=agent_run_state.run_id)
    AND NOT EXISTS (SELECT 1 FROM agent_tool_approval a WHERE a.run_id=agent_run_state.run_id) LIMIT #{limit}
